import { test, expect } from '@playwright/test';

test.describe('Form Submission Confirmation Email', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/contact-form');
  });

  test('should display confirmation email after successful form submission', async ({ page }) => {
    // Locate and fill name input using getByLabel
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    // Locate and fill email input using getByLabel
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('john.doe@example.com');

    // Locate and fill message textarea using getByLabel
    const messageInput = page.getByLabel('Message');
    await messageInput.fill('This is a test message.');

    // Locate and click submit button using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for confirmation message to appear
    const confirmationMessage = page.getByText('Thank you for your message. A confirmation email has been sent.');
    await expect(confirmationMessage).toBeVisible();

    // Verify success state
    await expect(page).toHaveURL(/.*success/);

    // Verify confirmation email was sent
    const emailSentIndicator = page.getByText('Confirmation email sent');
    await expect(emailSentIndicator).toBeVisible();
  });

  test('should handle form submission with validation errors and not send confirmation email', async ({ page }) => {
    // Locate and fill name input using getByLabel
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('Jane Doe');

    // Locate and fill email input with invalid format using getByLabel
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('invalid-email');

    // Locate and fill message textarea using getByLabel
    const messageInput = page.getByLabel('Message');
    await messageInput.fill('This is a test message.');

    // Locate and click submit button using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify validation error message appears
    const emailError = page.getByText('Please enter a valid email address');
    await expect(emailError).toBeVisible();

    // Verify confirmation message does not appear
    const confirmationMessage = page.getByText('Thank you for your message. A confirmation email has been sent.');
    await expect(confirmationMessage).not.toBeVisible();

    // Verify form is still visible
    await expect(page).toHaveURL(/.*contact-form/);

    // Verify email sent indicator does not appear
    const emailSentIndicator = page.getByText('Confirmation email sent');
    await expect(emailSentIndicator).not.toBeVisible();
  });
});
